const items = $input.all();
const messages = [];

for (const item of items) {
  const d = item.json;
  const name = d.userName || 'Athlete';
  const lbsLeft = (d.latestWeight && d.goalWeight) ? (d.latestWeight - d.goalWeight).toFixed(1) : null;
  const sessions = d.weekSessions || 0;
  const goalDate = d.goalDate || null;

  let msg = `🤖 ${name}: `;
  if (sessions >= 4) {
    msg += `Great week — ${sessions} sessions completed. `;
  } else {
    msg += `${sessions} sessions this week. Every one counts. `;
  }
  if (lbsLeft) msg += `You're ${lbsLeft} lbs from your goal. `;
  if (goalDate) {
    const weeks = Math.ceil((new Date(goalDate) - new Date()) / (7 * 24 * 60 * 60 * 1000));
    if (weeks > 0) msg += `${weeks} weeks to go.`;
    else msg += `Goal date reached — keep pushing!`;
  }

  messages.push({ json: { userId: d.userId, name, message: msg } });
}

return messages;

const items = $input.all();
items.forEach(i => console.log('Coaching:', i.json.name, '→', i.json.message));
